pts=[(0,4),(0,13),(0,18),(0,24),(1,1),(1,2),(1,8),(1,11),(1,19),(2,11),(2,20),(2,23)]
import math
for i,p in enumerate(pts):
 for q in pts[i+1:]:
  dr=q[0]-p[0]; dc=q[1]-p[1]; g=math.gcd(abs(dr),abs(dc))
  if g>1:
   mid=[(p[0]+k*dr//g,p[1]+k*dc//g) for k in range(1,g)]
   print(p,q,'g',g,'mid',mid)
